  visibility TEXT NOT NULL,
  egress_policy TEXT NOT NULL,
  confidence REAL,
  confidence_band TEXT,
  evidence_ids TEXT NOT NULL,
  status TEXT CHECK (
    status IN ('current','superseded','retracted','tombstoned')
  ) NOT NULL DEFAULT 'current',
