);
CREATE TABLE dataset_exports (
  id TEXT PRIMARY KEY,
  ts TEXT NOT NULL,
  dataset TEXT NOT NULL,
  path TEXT NOT NULL,
  min_scope TEXT NOT NULL,
  min_label TEXT NOT NULL,
  min_grade REAL,
